diff --git a/src/sales.ts b/src/sales.ts
index cab95cc..a9c5419 100644
--- a/src/sales.ts
+++ b/src/sales.ts
@@ -6,3 +6,12 @@ export interface Sale {
 export function totalCents(sales: Sale[]): number {
   return sales.reduce((sum, sale) => sum + sale.cents, 0);
 }
+
+/** How much more, or less, each day took than the day before it, for days given in order. */
+export function dailyChanges(sales: Sale[]): number[] {
+  const changes: number[] = [];
+  for (let i = 1; i <= sales.length; i++) {
+    changes.push(sales[i].cents - sales[i - 1].cents);
+  }
+  return changes;
+}
